  const unpaid = world.get(itemId, Unpaid);
  if (!unpaid) return base;
  const shopkeeperId = Number(unpaid.shopkeeperId || 0) | 0;
  const price = Number(unpaid.price || 0);
  return `${base}::unpaid:${shopkeeperId}:${price}`;
}

